package com.fintrack.service;
import com.fintrack.dto.*; import com.fintrack.model.User; import com.fintrack.repository.UserRepository; import com.fintrack.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository repo;private final PasswordEncoder enc;private final JwtService jwt;public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(repo.existsByEmail(email))throw new IllegalArgumentException("Email is already registered");User u=new User();u.setName(r.name().trim());u.setEmail(email);u.setPhone(r.phone());u.setPassword(enc.encode(r.password()));repo.save(u);return response(u);} public AuthResponse login(LoginRequest r){User u=repo.findByEmail(r.email().trim().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!enc.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("Invalid email or password");return response(u);} private AuthResponse response(User u){return new AuthResponse(jwt.generate(u.getEmail(),u.getId()),u.getId(),u.getName(),u.getEmail(),u.getPhone());}}
